FOODS_BY_CITY=[
 {"name":"Zürcher Geschnetzeltes","name_en":"Zurich-style Sliced Veal","name_fr":"Émincé de veau à la zurichoise","name_es":"Ternera troceada al estilo de Zúrich","description":"Striscioline di vitello rosolate rapidamente con funghi in salsa cremosa al vino bianco, servite con rösti. La carne deve restare tenera e la salsa equilibrata, non coprire tutto con panna.","description_en":"Quickly sautéed veal strips and mushrooms in a white-wine cream sauce, served with rösti. The meat should remain tender and the sauce balanced rather than dominated by cream.","description_fr":"Fines lamelles de veau sautées avec champignons dans une sauce crème-vin blanc, servies avec rösti. La viande doit rester tendre et la sauce équilibrée, sans excès de crème.","description_es":"Tiras de ternera salteadas con champiñones en salsa de nata y vino blanco, servidas con rösti. La carne debe quedar tierna y la salsa equilibrada, sin exceso de nata.","ingredients":["vitello","funghi","vino bianco","panna","rösti"],"ingredients_en":["veal","mushrooms","white wine","cream","rösti"],"ingredients_fr":["veau","champignons","vin blanc","crème","rösti"],"ingredients_es":["ternera","champiñones","vino blanco","nata","rösti"],"places":["Kronenhalle Zürich","Zeughauskeller Zürich","Zunfthaus zur Waag Zürich"]},
 {"name":"Rösti","name_en":"Rösti","name_fr":"Rösti","name_es":"Rösti","description":"Patate grattugiate, spesso precotte, vengono compattate e dorate in padella fino a creare una crosta uniforme e un interno morbido. Nato come colazione contadina, è contorno o piatto con uovo, formaggio o pancetta.","description_en":"Grated, often pre-cooked potatoes are pressed and pan-browned into an even crust with a soft centre. Once a farm breakfast, it now works as a side or a dish with egg, cheese or bacon.","description_fr":"Des pommes de terre râpées, souvent précuites, sont tassées et dorées pour former une croûte régulière et un cœur tendre. Ancien petit déjeuner paysan, le rösti accompagne ou se garnit d'œuf, fromage ou lard.","description_es":"Patatas ralladas, a menudo precocidas, se compactan y doran hasta formar corteza uniforme e interior tierno. Antiguo desayuno campesino, sirve de guarnición o plato con huevo, queso o tocino.","ingredients":["patate","burro chiarificato","sale"],"ingredients_en":["potatoes","clarified butter","salt"],"ingredients_fr":["pommes de terre","beurre clarifié","sel"],"ingredients_es":["patatas","mantequilla clarificada","sal"],"places":["Swiss Chuchi Zürich","Raclette Factory Zürich","Zeughauskeller Zürich"]},
 {"name":"Zürcher Tirggel","name_en":"Zurich Tirggel","name_fr":"Tirggel zurichois","name_es":"Tirggel de Zúrich","description":"Biscotto sottile e duro al miele, pressato in stampi figurativi e tradizionalmente legato al periodo natalizio. Va apprezzato per profumo, disegno e consistenza croccante più che per morbidezza.","description_en":"A thin, hard honey biscuit pressed in figurative moulds and traditionally associated with Christmas. It is valued for aroma, design and crisp texture rather than softness.","description_fr":"Biscuit fin et dur au miel, pressé dans des moules figuratifs et traditionnellement lié à Noël. Il s'apprécie pour son parfum, son dessin et son croquant plutôt que pour le moelleux.","description_es":"Galleta fina y dura de miel, prensada en moldes figurativos y ligada a Navidad. Se aprecia por aroma, dibujo y textura crujiente más que por suavidad.","ingredients":["farina","miele","spezie"],"ingredients_en":["flour","honey","spices"],"ingredients_fr":["farine","miel","épices"],"ingredients_es":["harina","miel","especias"],"places":["Confiserie Honold Zürich","Confiserie Sprüngli Zürich","Café Schober Zürich"]},
 {"name":"Birchermüesli","name_en":"Bircher Muesli","name_fr":"Birchermüesli","name_es":"Muesli Bircher","description":"Fiocchi d'avena ammollati con mela grattugiata, latte o yogurt, limone e frutta secca. Creato dal medico zurighese Bircher-Benner, deve restare fresco e fruttato, non diventare soltanto un dessert zuccherato.","description_en":"Soaked oats with grated apple, milk or yoghurt, lemon and nuts. Created by Zurich physician Bircher-Benner, it should remain fresh and fruit-led rather than becoming a sugary dessert.","description_fr":"Flocons d'avoine trempés avec pomme râpée, lait ou yaourt, citron et noix. Créé par le médecin zurichois Bircher-Benner, il doit rester frais et fruité, pas devenir un dessert sucré.","description_es":"Avena remojada con manzana rallada, leche o yogur, limón y frutos secos. Creado por el médico zuriqués Bircher-Benner, debe ser fresco y frutal, no un postre azucarado.","ingredients":["avena","mela","yogurt","limone","frutta secca"],"ingredients_en":["oats","apple","yoghurt","lemon","nuts"],"ingredients_fr":["avoine","pomme","yaourt","citron","noix"],"ingredients_es":["avena","manzana","yogur","limón","frutos secos"],"places":["Haus Hiltl Zürich","Sprössling Zürich","Café Henrici Zürich"]},
 {"name":"Fondue al formaggio","name_en":"Cheese Fondue","name_fr":"Fondue au fromage","name_es":"Fondue de queso","description":"Formaggi svizzeri fusi con vino bianco e kirsch vengono condivisi immergendo cubi di pane. Pur non essendo esclusivamente zurighese, è un rito alpino diffuso: calore basso e miscela corretta evitano una massa separata o gommosa.","description_en":"Swiss cheeses melted with white wine and kirsch are shared by dipping bread cubes. Though not uniquely Zurich, it is a widespread Alpine ritual: low heat and the right blend prevent splitting or rubberiness.","description_fr":"Des fromages suisses fondus avec vin blanc et kirsch se partagent avec des cubes de pain. Sans être uniquement zurichoise, c'est un rite alpin: feu doux et bon mélange évitent séparation ou texture caoutchouteuse.","description_es":"Quesos suizos fundidos con vino blanco y kirsch se comparten mojando pan. Aunque no es solo de Zúrich, es un rito alpino: fuego bajo y mezcla correcta evitan separación o textura gomosa.","ingredients":["formaggio svizzero","vino bianco","kirsch","pane","aglio"],"ingredients_en":["Swiss cheese","white wine","kirsch","bread","garlic"],"ingredients_fr":["fromage suisse","vin blanc","kirsch","pain","ail"],"ingredients_es":["queso suizo","vino blanco","kirsch","pan","ajo"],"places":["Le Dézaley Zürich","Swiss Chuchi Zürich","Chäsalp Zürich"]},
 {"name":"Raclette","name_en":"Raclette","name_fr":"Raclette","name_es":"Raclette","description":"La superficie di una mezza forma viene fusa e raschiata su patate, cetriolini e cipolline. La porzione si mangia subito: il formaggio deve essere fluido e aromatico, sostenuto dall'acidità dei sottaceti.","description_en":"The surface of a half wheel is melted and scraped over potatoes, cornichons and pickled onions. It should be eaten immediately: fluid aromatic cheese balanced by pickle acidity.","description_fr":"La surface d'une demi-meule est fondue puis raclée sur pommes de terre, cornichons et petits oignons. À manger aussitôt: fromage fluide et aromatique équilibré par l'acidité.","description_es":"La superficie de media rueda se funde y raspa sobre patatas, pepinillos y cebollitas. Debe comerse al momento: queso fluido y aromático equilibrado por encurtidos.","ingredients":["formaggio raclette","patate","cetriolini","cipolline"],"ingredients_en":["raclette cheese","potatoes","cornichons","pickled onions"],"ingredients_fr":["fromage à raclette","pommes de terre","cornichons","petits oignons"],"ingredients_es":["queso raclette","patatas","pepinillos","cebollitas"],"places":["Raclette Factory Zürich","Chäsalp Zürich","Walliser Keller Zürich"]},
 {"name":"Bratwurst di San Gallo con Bürli","name_en":"St Gallen Bratwurst with Bürli","name_fr":"Bratwurst de Saint-Gall avec Bürli","name_es":"Bratwurst de San Galo con Bürli","description":"Salsiccia bianca fine di vitello e latte, grigliata e servita con il panino croccante Bürli. A Zurigo si trova facilmente; la tradizione evita la senape per non coprire il gusto delicato, anche se la scelta resta personale.","description_en":"A fine white veal-and-milk sausage grilled and served with a crisp Bürli roll. Common in Zurich, tradition avoids mustard so it does not mask the delicate flavour, though preference is personal.","description_fr":"Fine saucisse blanche de veau et lait grillée, servie avec un Bürli croustillant. Courante à Zurich, la tradition évite la moutarde pour préserver sa délicatesse, même si chacun choisit.","description_es":"Salchicha blanca fina de ternera y leche, asada y servida con pan Bürli crujiente. Común en Zúrich, la tradición evita mostaza para no tapar su sabor delicado, aunque es elección personal.","ingredients":["vitello","latte","spezie","pane Bürli"],"ingredients_en":["veal","milk","spices","Bürli roll"],"ingredients_fr":["veau","lait","épices","pain Bürli"],"ingredients_es":["ternera","leche","especias","pan Bürli"],"places":["Sternen Grill Zürich","Vorderer Sternen Zürich","Zeughauskeller Zürich"]},
 {"name":"Luxemburgerli","name_en":"Luxemburgerli","name_fr":"Luxemburgerli","name_es":"Luxemburgerli","description":"Piccoli macaron creati da Sprüngli, più leggeri e minuti dei classici francesi, con gusci di meringa e creme stagionali. La freschezza è essenziale perché umidità e ripieno modificano rapidamente la consistenza.","description_en":"Small macarons created by Sprüngli, lighter and smaller than classic French versions, with meringue shells and seasonal creams. Freshness is essential because humidity and filling quickly change the texture.","description_fr":"Petits macarons créés par Sprüngli, plus légers et petits que les classiques français, avec coques de meringue et crèmes saisonnières. La fraîcheur est essentielle car humidité et garniture changent vite la texture.","description_es":"Pequeños macarons creados por Sprüngli, más ligeros y pequeños que los franceses, con conchas de merengue y cremas estacionales. La frescura es esencial porque humedad y relleno cambian rápido la textura.","ingredients":["albume","mandorle","zucchero","crema"],"ingredients_en":["egg white","almonds","sugar","cream filling"],"ingredients_fr":["blanc d'œuf","amandes","sucre","crème"],"ingredients_es":["clara de huevo","almendras","azúcar","crema"],"places":["Confiserie Sprüngli Paradeplatz Zürich","Sprüngli Bahnhofstrasse Zürich","Sprüngli Hauptbahnhof Zürich"]},
]

CULTURE_FACTS=[
 fact("🚋",n("Il tram struttura la vita urbana","Trams structure urban life","Le tram structure la vie urbaine","El tranvía estructura la vida urbana"),n("La rete fitta permette di vivere senza auto e rende i quartieri leggibili attraverso nodi e frequenze.","The dense network supports car-free life and makes districts legible through hubs and frequency.","Le réseau dense permet de vivre sans voiture et rend les quartiers lisibles par ses nœuds et fréquences.","La red densa permite vivir sin coche y hace legibles los barrios mediante nodos y frecuencias.")),
 fact("💧",n("Le fontane sono acqua potabile","Fountains provide drinking water","Les fontaines donnent de l'eau potable","Las fuentes ofrecen agua potable"),n("La città conta numerose fontane pubbliche: salvo indicazione contraria, l'acqua è potabile e riduce la necessità di bottiglie.","The city has many public fountains; unless marked otherwise, their water is drinkable and reduces bottle use.","La ville compte de nombreuses fontaines; sauf indication contraire, leur eau est potable et limite les bouteilles.","La ciudad tiene numerosas fuentes; salvo indicación contraria, el agua es potable y reduce el uso de botellas.")),
 fact("🎭",n("Dada nacque in esilio","Dada was born in exile","Dada est né en exil","Dadá nació en el exilio"),n("Artisti internazionali riuniti al Cabaret Voltaire nel 1916 reagirono alla guerra con poesia, performance e rottura delle regole.","International artists at Cabaret Voltaire in 1916 reacted to war through poetry, performance and broken conventions.","Des artistes internationaux au Cabaret Voltaire en 1916 réagirent à la guerre par poésie, performance et rupture des règles.","Artistas internacionales en Cabaret Voltaire en 1916 reaccionaron a la guerra con poesía, actuación y ruptura de reglas.")),
 fact("🏊",n("Il lago è anche uno spazio balneare","The lake is also a swimming space","Le lac est aussi un espace de baignade","El lago también es espacio de baño"),n("Badi e rive trasformano l'acqua in infrastruttura sociale estiva; accessi, correnti e stagione vanno rispettati.","Lidos and shores turn water into summer social infrastructure; access rules, currents and season must be respected.","Bains et rives transforment l'eau en infrastructure sociale estivale; accès, courants et saison doivent être respectés.","Balnearios y orillas convierten el agua en infraestructura social de verano; hay que respetar accesos, corrientes y temporada.")),
 fact("⚖️",n("La città è ricca ma non è la capitale","The wealthy city is not the capital","La ville riche n'est pas la capitale","La ciudad rica no es la capital"),n("Zurigo è il maggiore centro economico svizzero, mentre la sede federale è Berna: una distinzione utile per capire il paese.","Zurich is Switzerland's largest economic centre, while the federal seat is Bern, a useful distinction for understanding the country.","Zurich est le principal centre économique suisse, tandis que le siège fédéral est Berne, distinction utile pour comprendre le pays.","Zúrich es el mayor centro económico suizo, mientras la sede federal es Berna, distinción útil para entender el país.")),
 fact("🗳️",n("La democrazia diretta è quotidiana","Direct democracy is everyday","La démocratie directe est quotidienne","La democracia directa es cotidiana"),n("Votazioni frequenti e manifesti pubblici rendono visibili decisioni comunali, cantonali e federali nello spazio urbano.","Frequent votes and public posters make municipal, cantonal and federal decisions visible in urban space.","Votes fréquents et affiches rendent visibles les décisions communales, cantonales et fédérales dans l'espace urbain.","Votaciones frecuentes y carteles hacen visibles decisiones municipales, cantonales y federales en el espacio urbano.")),
 fact("🌐",n("Lo svizzero tedesco domina il parlato","Swiss German dominates speech","Le suisse allemand domine à l'oral","El alemán suizo domina el habla"),n("Il tedesco standard si usa per scrittura e contesti formali, mentre nella conversazione quotidiana prevalgono dialetti alemanni.","Standard German is used in writing and formal contexts, while Alemannic dialects dominate everyday conversation.","L'allemand standard sert à l'écrit et dans les contextes formels, tandis que les dialectes alémaniques dominent la conversation.","El alemán estándar se usa por escrito y en contextos formales, mientras dialectos alemánicos dominan la conversación.")),
 fact("♻️",n("Spazio e rifiuti sono gestiti con precisione","Space and waste are managed precisely","Espace et déchets sont gérés avec précision","Espacio y residuos se gestionan con precisión"),n("Raccolta, riciclo e uso dei parchi seguono regole chiare; comportamento discreto e rispetto degli spazi sono parte dell'esperienza locale.","Collection, recycling and park use follow clear rules; discreet behaviour and respect for space are part of local life.","Collecte, recyclage et usage des parcs suivent des règles claires; discrétion et respect des lieux font partie de la vie locale.","Recogida, reciclaje y uso de parques siguen reglas claras; discreción y respeto del espacio forman parte de la vida local.")),
 fact("⛪",n("La Riforma cambiò chiese e città","The Reformation reshaped churches and city","La Réforme transforma églises et ville","La Reforma transformó iglesias y ciudad"),n("Zwingli predicò al Grossmünster e la Riforma zurighese modificò liturgia, immagini religiose, istruzione e governo civico.","Zwingli preached at Grossmünster, and Zurich's Reformation changed worship, religious imagery, education and civic government.","Zwingli prêcha au Grossmünster et la Réforme zurichoise modifia culte, images religieuses, éducation et gouvernement civique.","Zwinglio predicó en Grossmünster y la Reforma de Zúrich cambió culto, imágenes religiosas, educación y gobierno cívico.")),
 fact("🏔️",n("Le Alpi sono una presenza visiva, non urbana","The Alps are visible but not within the city","Les Alpes sont visibles, mais pas dans la ville","Los Alpes son visibles, pero no están en la ciudad"),n("Con aria limpida il lago inquadra le cime lontane; l'Uetliberg è il rilievo cittadino accessibile, mentre le escursioni alpine richiedono treno e pianificazione separata.","In clear weather the lake frames distant peaks; Uetliberg is the accessible city hill, while Alpine excursions require trains and separate planning.","Par temps clair, le lac cadre les sommets lointains; l'Uetliberg est la colline urbaine accessible, tandis que les Alpes exigent train et préparation distincte.","Con tiempo despejado el lago enmarca cumbres lejanas; Uetliberg es la colina urbana accesible, mientras las excursiones alpinas requieren tren y planificación aparte.")),
]

CITY_INFO={"city":CITY_ID,"currency":"Franco svizzero (CHF)","currency_en":"Swiss franc (CHF)","currency_fr":"Franc suisse (CHF)","currency_es":"Franco suizo (CHF)","language":"Tedesco; svizzero tedesco nel parlato","language_en":"German; Swiss German in speech","language_fr":"Allemand; suisse allemand à l'oral","language_es":"Alemán; alemán suizo hablado","english_level":"molto alto","english_note":"L'inglese è ampiamente compreso nei servizi e tra i giovani, ma saluti in tedesco sono apprezzati.","english_note_en":"English is widely understood in services and among younger people, though German greetings are appreciated.","english_note_fr":"L'anglais est largement compris dans les services et chez les jeunes, mais les salutations en allemand sont appréciées.","english_note_es":"El inglés se entiende ampliamente en servicios y entre jóvenes, aunque se agradecen saludos en alemán.","timezone":"CET (UTC+1), CEST (UTC+2) in estate","timezone_en":"CET (UTC+1), CEST (UTC+2) in summer","timezone_fr":"CET (UTC+1), CEST (UTC+2) en été","timezone_es":"CET (UTC+1), CEST (UTC+2) en verano","voltage":"230 V, prese tipo J; spine europee sottili tipo C spesso compatibili","voltage_en":"230 V, type J sockets; slim European type C plugs often fit","voltage_fr":"230 V, prises type J; fiches européennes fines type C souvent compatibles","voltage_es":"230 V, enchufes tipo J; clavijas europeas finas tipo C suelen ser compatibles","water":"L'acqua del rubinetto e delle fontane non segnalate diversamente è potabile e di ottima qualità.","water_en":"Tap water and water from fountains not marked otherwise are safe and excellent.","water_fr":"L'eau du robinet et des fontaines non signalées autrement est potable et excellente.","water_es":"El agua del grifo y de fuentes sin señal contraria es potable y excelente.","tipping":"Il servizio è incluso; arrotondare o lasciare circa il 5-10% per un buon servizio è comune ma facoltativo.","tipping_en":"Service is included; rounding up or leaving around 5-10% for good service is common but optional.","tipping_fr":"Le service est inclus; arrondir ou laisser environ 5-10% pour un bon service est courant mais facultatif.","tipping_es":"El servicio está incluido; redondear o dejar alrededor del 5-10% por buen servicio es común pero opcional.","emergency_numbers":[{"label":"Emergenze generali","label_en":"General emergency","label_fr":"Urgences générales","label_es":"Emergencias generales","number":"112"},{"label":"Polizia","label_en":"Police","label_fr":"Police","label_es":"Policía","number":"117"},{"label":"Ambulanza","label_en":"Ambulance","label_fr":"Ambulance","label_es":"Ambulancia","number":"144"}],"transport_apps":[{"name":"ZVV","description":"Orari, biglietti e rete integrata di tram, bus, treni, battelli e funicolari.","description_en":"Timetables, tickets and the integrated tram, bus, train, boat and funicular network.","description_fr":"Horaires, billets et réseau intégré de trams, bus, trains, bateaux et funiculaires.","description_es":"Horarios, billetes y red integrada de tranvías, buses, trenes, barcos y funiculares.","ios_url":"https://www.zvv.ch/zvv/en/service/apps/zvv-app.html","android_url":"https://www.zvv.ch/zvv/en/service/apps/zvv-app.html"}],"useful_apps":[{"name":"Zürich City Guide","description":"Guida ufficiale e accesso alle informazioni sulla Zürich Card.","description_en":"Official guide and access to Zürich Card information.","description_fr":"Guide officiel et accès aux informations de la Zürich Card.","description_es":"Guía oficial y acceso a información de la Zürich Card.","ios_url":"https://www.zuerich.com/en/zurichcard/city-guide-app","android_url":"https://www.zuerich.com/en/zurichcard/city-guide-app"}],"quick_tips":["Acquista il biglietto prima di salire: la rete usa controlli a campione.","Lo stesso titolo ZVV copre i mezzi inclusi nelle zone acquistate, anche battelli e funicolari.","Prezzi di ristoranti e alloggi sono elevati: supermercati e fontane aiutano il budget.","Per l'Uetliberg controlla visibilità e fondo dei sentieri prima di partire.","Il bagno nel lago è consentito solo dove condizioni e accessi sono adeguati."],"quick_tips_en":["Buy a ticket before boarding: the network uses random inspections.","The same ZVV ticket covers included transport in purchased zones, including boats and funiculars.","Restaurants and lodging are expensive: supermarkets and fountains help the budget.","Check visibility and trail conditions before going to Uetliberg.","Swim in the lake only where conditions and access are suitable."],"quick_tips_fr":["Achetez votre billet avant de monter: le réseau pratique des contrôles aléatoires.","Le même titre ZVV couvre les transports des zones achetées, bateaux et funiculaires compris.","Restaurants et logements sont chers: supermarchés et fontaines aident le budget.","Vérifiez visibilité et état des sentiers avant l'Uetliberg.","Baignez-vous dans le lac seulement là où accès et conditions conviennent."],"quick_tips_es":["Compra el billete antes de subir: la red realiza controles aleatorios.","El mismo billete ZVV cubre los transportes de las zonas compradas, incluidos barcos y funiculares.","Restaurantes y alojamiento son caros: supermercados y fuentes ayudan al presupuesto.","Comprueba visibilidad y senderos antes de ir al Uetliberg.","Báñate en el lago solo donde acceso y condiciones sean adecuados."]}

NEIGHBORHOODS=[
 neighborhood(41,CITY_ID,n("Altstadt","Old Town","Vieille Ville","Casco antiguo"),n("Pro: monumenti, lago e stazione raggiungibili a piedi. Pro: atmosfera storica e ristoranti. Contro: prezzi molto elevati. Contro: rumore serale a Niederdorf.","Pros: sights, lake and station are walkable. Pros: historic atmosphere and restaurants. Cons: very high prices. Cons: evening noise in Niederdorf.","Avantages: sites, lac et gare à pied. Avantages: ambiance historique et restaurants. Inconvénients: prix très élevés. Inconvénients: bruit le soir à Niederdorf.","Ventajas: monumentos, lago y estación a pie. Ventajas: ambiente histórico y restaurantes. Desventajas: precios muy altos. Desventajas: ruido nocturno en Niederdorf."),["centrale","attrazioni","vita notturna"]),
 neighborhood(42,CITY_ID,n("Enge","Enge","Enge","Enge"),n("Pro: lago, parchi e collegamenti ferroviari. Pro: ambiente elegante e tranquillo. Contro: ristorazione e alloggi costosi. Contro: meno vita serale spontanea.","Pros: lake, parks and rail links. Pros: elegant and quiet setting. Cons: expensive dining and lodging. Cons: less spontaneous nightlife.","Avantages: lac, parcs et trains. Avantages: cadre élégant et calme. Inconvénients: restaurants et logements chers. Inconvénients: peu de vie nocturne spontanée.","Ventajas: lago, parques y trenes. Ventajas: entorno elegante y tranquilo. Desventajas: restaurantes y alojamiento caros. Desventajas: poca vida nocturna espontánea."),["lungomare","lusso","tranquillo"]),
 neighborhood(43,CITY_ID,n("Zürich-West","Zurich-West","Zurich-West","Zürich-West"),n("Pro: design, locali e vita serale. Pro: treni e tram frequenti. Contro: atmosfera industriale poco classica. Contro: rumore attorno ai locali nel fine settimana.","Pros: design, venues and nightlife. Pros: frequent trains and trams. Cons: industrial rather than classic atmosphere. Cons: weekend venue noise.","Avantages: design, adresses et sorties. Avantages: trains et trams fréquents. Inconvénients: ambiance industrielle peu classique. Inconvénients: bruit le week-end.","Ventajas: diseño, locales y vida nocturna. Ventajas: trenes y tranvías frecuentes. Desventajas: ambiente industrial poco clásico. Desventajas: ruido de fin de semana."),["arte","vita notturna","trasporti"]),
 neighborhood(44,CITY_ID,n("Wiedikon","Wiedikon","Wiedikon","Wiedikon"),n("Pro: ristoranti locali e atmosfera residenziale. Pro: centro vicino con tram e treni. Contro: poche attrazioni principali. Contro: alcune zone richiedono cambi di mezzo.","Pros: local restaurants and residential feel. Pros: centre nearby by tram and train. Cons: few major sights. Cons: some areas require transfers.","Avantages: restaurants locaux et ambiance résidentielle. Avantages: centre proche en tram et train. Inconvénients: peu de sites majeurs. Inconvénients: correspondances selon le secteur.","Ventajas: restaurantes locales y ambiente residencial. Ventajas: centro cercano en tranvía y tren. Desventajas: pocos lugares principales. Desventajas: algunas zonas requieren transbordo."),["residenziale","gastronomico","trasporti"]),
 neighborhood(45,CITY_ID,n("Oerlikon","Oerlikon","Oerlikon","Oerlikon"),n("Pro: collegamenti rapidissimi con aeroporto e centro. Pro: alloggi spesso più funzionali. Contro: distanza dal lago e centro storico. Contro: atmosfera orientata a residenti ed eventi.","Pros: very fast airport and centre links. Pros: often more functional lodging. Cons: distance from lake and old town. Cons: atmosphere geared to residents and events.","Avantages: liaisons très rapides vers aéroport et centre. Avantages: logements souvent fonctionnels. Inconvénients: loin du lac et de la vieille ville. Inconvénients: ambiance tournée vers habitants et événements.","Ventajas: conexiones muy rápidas con aeropuerto y centro. Ventajas: alojamiento a menudo funcional. Desventajas: lejos del lago y casco antiguo. Desventajas: ambiente orientado a residentes y eventos."),["trasporti","moderno","residenziale"]),
 neighborhood(46,CITY_ID,n("Seefeld","Seefeld","Seefeld","Seefeld"),n("Pro: lago, passeggiate e centro vicini. Pro: quartiere sicuro e ordinato. Contro: prezzi tra i più alti. Contro: atmosfera poco economica e vita notturna contenuta.","Pros: lake, walks and centre nearby. Pros: safe and orderly district. Cons: among the highest prices. Cons: little budget life and restrained nightlife.","Avantages: lac, promenades et centre proches. Avantages: quartier sûr et ordonné. Inconvénients: prix parmi les plus élevés. Inconvénients: peu d'options économiques et sorties limitées.","Ventajas: lago, paseos y centro cercanos. Ventajas: barrio seguro y ordenado. Desventajas: precios de los más altos. Desventajas: pocas opciones económicas y ocio limitado."),["lungomare","lusso","tranquillo"]),
]
